package httpapi
import("encoding/json";"errors";"log/slog";"net/http";"strings";"time";"github.com/go-chi/chi/v5";"github.com/go-chi/chi/v5/middleware";"github.com/golang-jwt/jwt/v5";"github.com/google/uuid";"golang.org/x/crypto/bcrypt";"github.com/saurabhkumaryadav2001/recall-api/internal/config";"github.com/saurabhkumaryadav2001/recall-api/internal/store")
type API struct{s *store.Store;c config.Config;l *slog.Logger}
type key string
const userKey key="uid"
func New(s *store.Store,c config.Config,l *slog.Logger)http.Handler{a:=&API{s,c,l};r:=chi.NewRouter();r.Use(middleware.RequestID,middleware.RealIP,middleware.Recoverer,middleware.Timeout(20*time.Second));r.Get("/healthz",func(w http.ResponseWriter,r *http.Request){write(w,200,map[string]string{"status":"ok"})});r.Get("/readyz",func(w http.ResponseWriter,r *http.Request){if s.DB.Ping(r.Context())!=nil{write(w,503,map[string]string{"status":"not_ready"});return};write(w,200,map[string]string{"status":"ready"})});r.Route("/v1",func(v chi.Router){v.Post("/auth/register",a.register);v.Post("/auth/login",a.login);v.Group(func(p chi.Router){p.Use(a.auth);p.Get("/memories",a.list);p.Post("/memories",a.create);p.Get("/memories/{id}",a.get);p.Put("/memories/{id}",a.update);p.Delete("/memories/{id}",a.delete)})});return r}
func write(w http.ResponseWriter,n int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(n);_ =json.NewEncoder(w).Encode(v)}
func fail(w http.ResponseWriter,n int,s string){write(w,n,map[string]string{"error":s})}
func decode(r *http.Request,v any)error{d:=json.NewDecoder(r.Body);d.DisallowUnknownFields();return d.Decode(v)}
func(a *API)register(w http.ResponseWriter,r *http.Request){var x struct{Email string `json:"email"`;Password string `json:"password"`};if decode(r,&x)!=nil{fail(w,400,"invalid JSON");return};x.Email=strings.ToLower(strings.TrimSpace(x.Email));if !strings.Contains(x.Email,"@")||len(x.Password)<12||len(x.Password)>72{fail(w,400,"valid email and password (12-72 chars) required");return};h,e:=bcrypt.GenerateFromPassword([]byte(x.Password),bcrypt.DefaultCost);if e!=nil{fail(w,500,"password hashing failed");return};id,e:=a.s.CreateUser(r.Context(),x.Email,string(h));if e!=nil{fail(w,409,"email already registered");return};t,e:=a.token(id);if e!=nil{fail(w,500,"token error");return};write(w,201,map[string]any{"access_token":t,"token_type":"Bearer","expires_in":int(a.c.TokenTTL.Seconds())})}
func(a *API)login(w http.ResponseWriter,r *http.Request){var x struct{Email string `json:"email"`;Password string `json:"password"`};if decode(r,&x)!=nil{fail(w,400,"invalid JSON");return};u,e:=a.s.User(r.Context(),strings.ToLower(strings.TrimSpace(x.Email)));if e!=nil||bcrypt.CompareHashAndPassword([]byte(u.Hash),[]byte(x.Password))!=nil{fail(w,401,"invalid credentials");return};t,e:=a.token(u.ID);if e!=nil{fail(w,500,"token error");return};write(w,200,map[string]any{"access_token":t,"token_type":"Bearer","expires_in":int(a.c.TokenTTL.Seconds())})}
func(a *API)token(id uuid.UUID)(string,error){return jwt.NewWithClaims(jwt.SigningMethodHS256,jwt.RegisteredClaims{Subject:id.String(),Issuer:"recall-api",ExpiresAt:jwt.NewNumericDate(time.Now().Add(a.c.TokenTTL)),IssuedAt:jwt.NewNumericDate(time.Now())}).SignedString([]byte(a.c.JWTSecret))}
func(a *API)auth(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){h:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ");if h==r.Header.Get("Authorization")||h==""{fail(w,401,"bearer token required");return};t,e:=jwt.ParseWithClaims(h,&jwt.RegisteredClaims{},func(t *jwt.Token)(any,error){if t.Method!=jwt.SigningMethodHS256{return nil,errors.New("unexpected signing method")};return []byte(a.c.JWTSecret),nil},jwt.WithIssuer("recall-api"));if e!=nil||!t.Valid{fail(w,401,"invalid/expired token");return};cl,ok:=t.Claims.(*jwt.RegisteredClaims);if !ok{fail(w,401,"invalid token");return};id,e:=uuid.Parse(cl.Subject);if e!=nil{fail(w,401,"invalid subject");return};next.ServeHTTP(w,r.WithContext(context.WithValue(r.Context(),userKey,id)))})}
